#[cfg(test)]
mod trade_report_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_trade_report_codec() {
        let original = TradeReport {
            req_id: 123456789,
            channel_id: 1234,
            adapter: 42,
            account: "a".repeat(16),
            cl_ord_id: "a".repeat(16),
            order_id: "a".repeat(16),
            exec_id: "a".repeat(16),
            exec_type: 42,
            ord_status: 42,
            security_id: "a".repeat(12),
            side: 42,
            last_px: -123456789,
            last_qty: -123456789,
            cum_qty: -123456789,
            leaves_qty: -123456789,
            ts_ns: 123456789,
            raw_ref: 123456789,
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let mut bytes = buf.freeze();

        let decoded = TradeReport::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
    }
}
